/**
 * A Dialog preset for confirming an action (`design/components/confirm-dialog.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/confirm-dialog.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  BORROWED,
  IDENTITY,
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  provide,
  scope,
  watchEffect,
  type BorrowedHolder,
  type Defaults,
} from '@polymorph/solid'
import Button from '../controls/Button'
import Dialog from './Dialog'
import FormField from '../controls/FormField'
import Input from '../controls/Input'

export type ConfirmTone = NonNullable<ConfirmDialogProps['tone']>

export interface ConfirmDialogProps {
  cancelLabel?: string
  closeLabel?: string
  /**
   * The action's verb; it has no default, so the caller must name the action.
   */
  confirmLabel: string
  /**
   * A typed confirmation: the phrase the person types before the confirm enables, such as the
   * name of the project being deleted. The body draws its field, and focus starts there in both
   * tones.
   */
  confirmWith?: string
  /**
   * The phrase field's error while its text cannot become the phrase, `The text does not match`
   * by default.
   */
  confirmWithError?: string
  /**
   * The phrase field's label, `Type {confirmWith} to confirm` by default. Localized hosts pass
   * their own, with the phrase in it.
   */
  confirmWithLabel?: string
  /**
   * Required, because a confirm must say what is at stake.
   */
  description: string
  /**
   * A Promise puts the dialog into its pending state until it settles.
   */
  onConfirm: () => void | Promise<void>
  onOpenChange?: (open: boolean) => void
  open?: boolean
  /**
   * Dialog's `presentation`, passed through (the sheet presentation,
   * `design/components/README.md`). A confirm is the content-light dialog this option is for.
   * `'sheet'` keeps the sm card above `30rem` and uses a bottom sheet below it. Footer order,
   * cancel-first initial focus and the pending lock are the same in both forms.
   */
  presentation?: 'auto' | 'sheet'
  title: string
  /**
   * `accent` for consequential but safe actions; the `danger` default is for destructive ones.
   */
  tone?: 'accent' | 'danger'
  trigger?: JSX.Element
}

/** A Dialog preset for confirming an action. */
export default function ConfirmDialog(given: ConfirmDialogProps): JSX.Element {
  const props = mergeProps(
    {
      closeLabel: 'Close',
      tone: 'danger',
      cancelLabel: 'Cancel',
      presentation: 'auto',
      confirmWithError: 'The text does not match',
    } as Defaults<
      ConfirmDialogProps,
      'closeLabel' | 'tone' | 'cancelLabel' | 'presentation' | 'confirmWithError'
    >,
    claimSlot(given),
  )
  return scope(() => {
    provide(IDENTITY, 'confirm-dialog')
    const borrowed: BorrowedHolder = {}
    provide(BORROWED, borrowed)
    const mirror = createCell(false)
    const pending = createCell(false)
    const typed = createCell('')
    const current = createDerived(() => props.open ?? mirror.value)
    const phrase = createDerived(() =>
      props.confirmWith === undefined ? undefined : props.confirmWith.trim().toLowerCase(),
    )
    const entered = createDerived(() => typed.value.trim().toLowerCase())
    const holds = createDerived(() => phrase.value === undefined || entered.value === phrase.value)
    const wrong = createDerived(
      () =>
        phrase.value !== undefined &&
        entered.value !== '' &&
        !phrase.value.startsWith(entered.value),
    )
    const setOpen = createDerived(() => (next: boolean) => {
      mirror.value = next
      props.onOpenChange?.(next)
    })
    const confirm = createDerived(() => async () => {
      const result = (
        props.onConfirm as unknown as ((...args: unknown[]) => unknown) | undefined
      )?.()
      if (!(result instanceof Promise)) {
        setOpen.value(false)
        return
      }
      pending.value = true
      try {
        await result
        setOpen.value(false)
      } finally {
        pending.value = false
      }
    })
    const effect1 = () => {
      void (current.value && (typed.value = ''))
    }
    watchEffect(
      createMemo(() => current.value),
      effect1,
      false,
    )
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const ran = agentMember({
        member: 'ConfirmDialog',
        element: () => borrowed.element?.(),
        state: () => ({ open: current.value, pending: pending.value }),
        actions: {
          cancel: () =>
            (() => {
              if (pending.value)
                throw new Error('The confirmed action is running; it cannot be cancelled.')
              setOpen.value(false)
            })(),
        },
        withholds: () => borrowed.element?.(),
      })
      release2 = () => {
        ran()
      }
    }
    onMount(effect2)
    onCleanup(() => release2?.())
    return (
      <Dialog
        closeLabel={props.closeLabel}
        size="sm"
        title={props.title}
        description={props.description}
        open={current.value}
        presentation={props.presentation}
        dismissible={!pending.value}
        alert={props.tone === 'danger'}
        initialFocus={
          props.tone === 'danger' && props.confirmWith === undefined ? 'dismiss' : 'primary'
        }
        onOpenChange={($event) => setOpen.value($event)}
        trigger={props.trigger}
        footer={
          <>
            <Button
              variant="outline"
              tone="neutral"
              label={props.cancelLabel}
              disabled={pending.value}
              onClick={() => setOpen.value(false)}
            />
            <Button
              variant="solid"
              tone={props.tone}
              label={props.confirmLabel}
              loading={pending.value}
              disabled={!holds.value}
              onClick={() => confirm.value()}
            />
          </>
        }
      >
        {props.confirmWith !== undefined ? (
          <FormField
            label={props.confirmWithLabel ?? `Type ${props.confirmWith} to confirm`}
            error={wrong.value ? props.confirmWithError : undefined}
          >
            <Input
              value={typed.value}
              autoComplete="off"
              exact={true}
              disabled={pending.value}
              onChange={($event) => (typed.value = $event)}
            />
          </FormField>
        ) : undefined}
      </Dialog>
    )
  })
}
